import React, { useEffect, useState } from "react";
import axios from "axios";
import { FaQuestionCircle, FaClipboardCheck, FaBookOpen } from "react-icons/fa";
import AlertBox from "./AlertBox";

function QuizStudent() {
  const studentId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState("");
  const [quizzes, setQuizzes] = useState([]);
  const [selectedQuiz, setSelectedQuiz] = useState("");
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState({});
  const [scoreData, setScoreData] = useState(null);
  const [alert, setAlert] = useState(null);

  useEffect(() => {
    const fetchEnrolledCourses = async () => {
      try {
        const res = await axios.get("http://127.0.0.1:8000/courses");
        const allCourses = res.data.courses || [];

        const enrollRes = await axios.get(
          `http://127.0.0.1:8000/enrollments/${studentId}`
        );

        const enrolledIds = enrollRes.data.map((e) => e.course_id);

        const myCourses = allCourses.filter((c) =>
          enrolledIds.includes(c.id)
        );

        setCourses(myCourses);
      } catch (error) {
        console.error(error);
      }
    };

    fetchEnrolledCourses();
  }, [studentId]);

  const loadQuizzesByCourse = async (courseId) => {
    try {
      const res = await axios.get(
        `http://127.0.0.1:8000/quizzes/course-details/${courseId}`
      );
      setQuizzes(res.data.quizzes || []);
      setQuestions([]);
      setSelectedQuiz("");
      setScoreData(null);
      setAnswers({});
    } catch (error) {
      console.error(error);
      setQuizzes([]);
    }
  };

  const loadQuizQuestions = async (quizId) => {
    try {
      const res = await axios.get(`http://127.0.0.1:8000/quiz/${quizId}`);
      setQuestions(res.data.questions || []);
      setScoreData(null);
      setAnswers({});
    } catch (error) {
      console.error(error);
      setQuestions([]);
    }
  };

  const handleSubmitQuiz = async () => {
    if (!selectedQuiz) {
      setAlert({
        message: "Please select a quiz first",
        type: "error"
      });
      return;
    }

    try {
      const res = await axios.post("http://127.0.0.1:8000/submit-quiz", {
        quiz_id: parseInt(selectedQuiz),
        student_id: parseInt(studentId),
        answers
      });

      setScoreData(res.data);
      setAlert({
        message: "Quiz submitted successfully",
        type: "success"
      });
    } catch (error) {
      console.error(error);
      setAlert({
        message: "Quiz submission failed",
        type: "error"
      });
    }
  };
  

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <div style={panelStyle}>
        <h2 style={{ color: "#6a1b9a", marginBottom: "20px" }}>
          Student Quiz Panel
        </h2>

        <div style={{ display: "grid", gap: "15px", marginBottom: "25px" }}>
          <div>
            <label><strong>Select Subject</strong></label>
            <select
              value={selectedCourse}
              onChange={(e) => {
                setSelectedCourse(e.target.value);
                loadQuizzesByCourse(e.target.value);
              }}
              style={inputStyle}
            >
              <option value="">Select Subject</option>
              {courses.map((course) => (
                <option key={course.id} value={course.id}>
                  {course.title} ({course.subject_code})
                </option>
              ))}
            </select>
          </div>

          {quizzes.length > 0 && (
            <div>
              <label><strong>Select Quiz</strong></label>
              <select
                value={selectedQuiz}
                onChange={(e) => {
                  setSelectedQuiz(e.target.value);
                  loadQuizQuestions(e.target.value);
                }}
                style={inputStyle}
              >
                <option value="">Select Quiz</option>
                {quizzes.map((quiz) => (
                  <option key={quiz.id} value={quiz.id}>
                    {quiz.title} - Teacher: {quiz.teacher_name}
                  </option>
                ))}
              </select>
            </div>
          )}
        </div>

        {quizzes.length > 0 && (
          <div style={{ marginBottom: "20px" }}>
            <h3 style={{ color: "#4a148c" }}>Available Quizzes</h3>
            {quizzes.map((quiz) => (
              <div key={quiz.id} style={quizCard}>
                <p style={{ margin: 0 }}>
                  <FaBookOpen style={{ marginRight: "8px", color: "#7b1fa2" }} />
                  <strong>{quiz.title}</strong>
                </p>
                <p style={{ marginTop: "8px" }}>
                  Teacher: <strong>{quiz.teacher_name}</strong>
                </p>
              </div>
            ))}
          </div>
        )}

        {questions.length > 0 ? (
          <>
            <h3 style={{ color: "#4a148c", marginBottom: "15px" }}>
              <FaQuestionCircle style={{ marginRight: "8px" }} />
              Quiz Questions
            </h3>

            {questions.map((q, index) => (
              <div key={q.id} style={questionCard}>
                <h3>
                  Q{index + 1}. {q.question}
                </h3>

                {[q.option1, q.option2, q.option3, q.option4].map((opt, i) => (
                  <label key={i} style={optionStyle}>
                    <input
                      type="radio"
                      name={`question-${q.id}`}
                      value={opt}
                      onChange={(e) =>
                        setAnswers({
                          ...answers,
                          [q.id]: e.target.value
                        })
                      }
                    />
                    <span style={{ marginLeft: "8px" }}>{opt}</span>
                  </label>
                ))}
              </div>
            ))}

            <button onClick={handleSubmitQuiz} style={submitBtn}>
              <FaClipboardCheck />
              Submit Quiz
            </button>
          </>
        ) : (
          selectedQuiz && <p>No questions found for this quiz.</p>
        )}

        {scoreData && (
          <div style={resultCard}>
            <h3>Quiz Result</h3>
            <p>
              Score: <strong>{scoreData.score}</strong> / {scoreData.total}
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

const panelStyle = {
  background: "#fff",
  borderRadius: "18px",
  padding: "20px",
  boxShadow: "0 6px 18px rgba(0,0,0,0.08)"
};

const inputStyle = {
  width: "100%",
  padding: "12px",
  borderRadius: "10px",
  border: "1px solid #ccc",
  marginTop: "8px",
  outline: "none"
};

const quizCard = {
  border: "1px solid #eee",
  borderRadius: "12px",
  padding: "14px",
  marginBottom: "10px",
  background: "#fafafa"
};

const questionCard = {
  border: "1px solid #eee",
  borderRadius: "12px",
  padding: "16px",
  marginBottom: "18px",
  background: "#fafafa"
};

const optionStyle = {
  display: "block",
  marginTop: "10px",
  padding: "8px",
  borderRadius: "8px"
};

const submitBtn = {
  background: "#7b1fa2",
  color: "#fff",
  border: "none",
  padding: "12px 18px",
  borderRadius: "10px",
  cursor: "pointer",
  fontWeight: "bold",
  display: "flex",
  alignItems: "center",
  gap: "8px"
};

const resultCard = {
  marginTop: "20px",
  padding: "16px",
  borderRadius: "12px",
  background: "#ede7f6"
};

export default QuizStudent;
